import React, { useState, useEffect } from "react";
import api from "../api/api";

export default function Dashboard() {
  const [data, setData] = useState(null);
  const [orders, setOrders] = useState([]);

  const fetchData = async () => {
    const [d, o] = await Promise.all([api.get("/dashboard"), api.get("/orders")]);
    setData(d.data);
    setOrders(o.data);
  };

  useEffect(() => {
    fetchData();
  }, []);

  const updateStatus = async (id, status) => {
    await api.put(`/orders/${id}/status`, { status });
    fetchData();
  };

  if (!data) return <p style={{ padding: 24 }}>Loading...</p>;
  const { reseller, affiliate } = data;

  return (
    <div className="page container">
      <h2 style={{ marginTop: 32 }}>Reseller Business</h2>
      <div className="stat-row">
        <Stat label="Total Orders" value={reseller.totalOrders} />
        <Stat label="Total Sales" value={`₹${reseller.totalSales}`} />
        <Stat label="Product Cost" value={`₹${reseller.totalCost}`} />
        <Stat label="Gross Margin" value={`₹${reseller.totalMargin}`} highlight />
      </div>

      <h3 className="section-title">Recent Orders</h3>
      <table>
        <thead>
          <tr>
            <th>Product</th><th>Customer</th><th>Qty</th><th>Paid ₹</th><th>Margin ₹</th><th>Status</th>
          </tr>
        </thead>
        <tbody>
          {orders.map((o) => (
            <tr key={o._id}>
              <td>{o.productName}</td>
              <td>{o.customerName} ({o.customerPhone})</td>
              <td>{o.quantity}</td>
              <td>{o.totalPaid}</td>
              <td>{o.totalMargin}</td>
              <td>
                <select value={o.status} onChange={(e) => updateStatus(o._id, e.target.value)}>
                  <option value="pending">Pending</option>
                  <option value="confirmed">Confirmed</option>
                  <option value="shipped">Shipped</option>
                  <option value="delivered">Delivered</option>
                  <option value="cancelled">Cancelled</option>
                </select>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <h2>Affiliate Business</h2>
      <p style={{ color: "var(--muted)", fontSize: 14 }}>
        Actual commission ka hisaab Flipkart Affiliate dashboard me milega — yahan hum sirf
        interest (clicks) track karte hain taaki pata chale kaunsa product kaam kar raha hai.
      </p>
      <div className="stat-row">
        <Stat label="Total Affiliate Clicks" value={affiliate.totalAffiliateClicks} accent />
      </div>

      <h3 className="section-title">Top Affiliate Products</h3>
      <table>
        <thead>
          <tr><th>Product</th><th>Source</th><th>Clicks</th></tr>
        </thead>
        <tbody>
          {affiliate.topProducts.map((p) => (
            <tr key={p.id}>
              <td>{p.name}</td>
              <td>{p.source}</td>
              <td>{p.clicks}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function Stat({ label, value, highlight, accent }) {
  return (
    <div className={`stat-card ${highlight ? "highlight" : ""} ${accent ? "accent" : ""}`}>
      <div className="label">{label}</div>
      <div className="value">{value}</div>
    </div>
  );
}
